-- 1. Cria a tabela principal de armazenamento
CREATE TABLE IF NOT EXISTS mgeditaveis_db (
    key TEXT PRIMARY KEY,
    data JSONB NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Habilita RLS e libera acesso com a chave de API
ALTER TABLE mgeditaveis_db ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Acesso Total MG" ON mgeditaveis_db;
CREATE POLICY "Acesso Total MG" ON mgeditaveis_db
    FOR ALL
    USING (true)
    WITH CHECK (true);

